package com.hsm.security;
import com.hsm.account.entity.User; import com.hsm.account.repository.UserRepository; import com.hsm.common.ApiException; import org.springframework.stereotype.Service; import java.time.*; import java.util.*; import java.util.concurrent.*;
@Service public class SessionService { private record Session(Long userId,Instant lastActivity){} private final Map<String,Session> sessions=new ConcurrentHashMap<>(); private final UserRepository users; public SessionService(UserRepository u){users=u;} public String create(User u){String token=UUID.randomUUID()+UUID.randomUUID().toString();sessions.put(token,new Session(u.getId(),Instant.now()));return token;} public User require(String token){Session s=sessions.get(token);if(s==null||s.lastActivity().plus(Duration.ofHours(1)).isBefore(Instant.now())){if(token!=null)sessions.remove(token);throw new ApiException(401,"UNAUTHENTICATED","Authentication is required.");}sessions.put(token,new Session(s.userId(),Instant.now()));return users.findById(s.userId()).orElseThrow(()->new ApiException(401,"UNAUTHENTICATED","Authentication is required."));} public void remove(String token){if(token!=null)sessions.remove(token);} }
